export default function (pi) {
  const hiddenDeclarations = (process.env.PISHARP_SKILL_READER_HIDE ?? "")
    .split(",").map(name => name.trim()).filter(Boolean);
  if (hiddenDeclarations.length === 0) return;
  pi.registerTool({
    name: "hidden_skill_reader_fixture",
    label: "Hidden reader fixture",
    description: "Fixture tool for hidden skill-reader prompt tests.",
    parameters: { type: "object", properties: {}, additionalProperties: false },
    prepareLoadout: () => ({ hiddenDeclarations }),
    execute: async () => ({ content: [{ type: "text", text: "hidden-reader fixture" }] }),
  });
}
